#!/usr/bin/env python3
"""Writes lib/l10n/keep_words.g.dart: AppLocalizations with Korean screen
text joined inside words, so lines break only between words (core keepWords).

Run after `flutter gen-l10n`; CI checks the output is up to date.
"""
import pathlib
import re

root = pathlib.Path(__file__).resolve().parent.parent
src = (root / 'lib/l10n/app_localizations.dart').read_text()
members = re.findall(r'^  String (get )?([a-zA-Z0-9_]+)(\(([^)]*)\))?;', src, re.M)

out = [
    '// Generated by tool/keep_words.py from app_localizations.dart. Do not edit.',
    '// ignore_for_file: type=lint',
    "import 'package:homefairy_core/homefairy_core.dart';",
    '',
    "import 'app_localizations.dart';",
    '',
    '/// [inner] with every string passed through [keepWords].',
    'class KeepWordsLocalizations extends AppLocalizations {',
    '  KeepWordsLocalizations(this.inner) : super(inner.localeName);',
    '',
    '  final AppLocalizations inner;',
]
for get, name, _, params in members:
    out.append('')
    out.append('  @override')
    if get:
        out.append(f'  String get {name} => keepWords(inner.{name});')
    else:
        args = ', '.join(p.strip().split(' ')[-1] for p in params.split(',') if p.strip())
        out.append(f'  String {name}({params}) => keepWords(inner.{name}({args}));')
out.append('}')
(root / 'lib/l10n/keep_words.g.dart').write_text('\n'.join(out) + '\n')
print(f'{len(members)} strings')
